    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst)
            wack_sync <= 3'b000;
        else
            wack_sync <= {wack_sync[1:0], m_wack};
    end
    wire s_wack = wack_sync[2];

    // S-side FSM
    reg s_w_state;
    wire s_w_idle = ~s_w_state;
    wire s_w_busy = s_w_state;

    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst) begin
            s_w_state   <= 1'b0;
            s_wdata_reg <= {DATA_WIDTH{1'b0}};
            s_wstrb_reg <= {STRB_WIDTH{1'b0}};
            s_wreq      <= 1'b0;
        end
        else begin
            if (s_w_idle && s_axil_wvalid) begin
                s_wdata_reg <= s_axil_wdata;
                s_wstrb_reg <= s_axil_wstrb;
                s_wreq      <= 1'b1;
                s_w_state   <= 1'b1;
            end
            else if (s_w_busy && s_wack) begin
                s_wreq  <= 1'b0;
                s_w_state <= 1'b0;
            end
        end
    end

    assign s_axil_wready = s_w_idle;

    // M-side FSM
    reg m_w_state;
    wire m_w_idle = ~m_w_state;
    wire m_w_busy = m_w_state;

    always @(posedge m_clk or posedge m_rst) begin
        if (m_rst) begin
            m_w_state <= 1'b0;
            m_wack    <= 1'b0;
        end
        else begin
            if (m_w_idle && m_wreq) begin
                m_w_state <= 1'b1;
            end
            else if (m_w_busy && m_axil_wready) begin
                m_w_state <= 1'b0;
                m_wack    <= 1'b1;
            end
            else if (m_wack) begin
                m_wack <= 1'b0;
            end
        end
    end

    assign m_axil_wdata  = s_wdata_reg;
    assign m_axil_wstrb  = s_wstrb_reg;
    assign m_axil_wvalid = m_w_busy;
    assign m_wack        = m_w_state;

    // ========================================================================
    // Write Response Channel: M -> S
    // ========================================================================
    reg  [1:0] m_bresp_reg;
    reg        m_breq;
    wire       s_back;

    // Synchronizer for request
    reg [2:0] breq_sync;
    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst)
            breq_sync <= 3'b000;
        else
            breq_sync <= {breq_sync[1:0], m_breq};
    end
    wire s_breq = breq_sync[2];

    // Synchronizer for acknowledge
    reg [2:0] back_sync;
    always @(posedge m_clk or posedge m_rst) begin
        if (m_rst)
            back_sync <= 3'b000;
        else
            back_sync <= {back_sync[1:0], s_back};
    end
    wire m_back = back_sync[2];

    // M-side FSM
    reg m_b_state;
    wire m_b_idle = ~m_b_state;
    wire m_b_busy = m_b_state;

    always @(posedge m_clk or posedge m_rst) begin
        if (m_rst) begin
            m_b_state   <= 1'b0;
            m_bresp_reg <= 2'b00;
            m_breq      <= 1'b0;
        end
        else begin
            if (m_b_idle && m_axil_bvalid) begin
                m_bresp_reg <= m_axil_bresp;
                m_breq      <= 1'b1;
                m_b_state   <= 1'b1;
            end
            else if (m_b_busy && m_back) begin
                m_breq  <= 1'b0;
                m_b_state <= 1'b0;
            end
        end
    end

    assign m_axil_bready = m_b_idle;

    // S-side FSM
    reg s_b_state;
    wire s_b_idle = ~s_b_state;
    wire s_b_busy = s_b_state;

    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst) begin
            s_b_state <= 1'b0;
            s_back    <= 1'b0;
        end
        else begin
            if (s_b_idle && s_breq) begin
                s_b_state <= 1'b1;
            end
            else if (s_b_busy && s_axil_bready) begin
                s_b_state <= 1'b0;
                s_back    <= 1'b1;
            end
            else if (s_back) begin
                s_back <= 1'b0;
            end
        end
    end

    assign s_axil_bresp  = m_bresp_reg;
    assign s_axil_bvalid = s_b_busy;
    assign s_back        = s_b_state;

