                s_araddr_reg <= s_axil_araddr;
                s_arprot_reg <= s_axil_arprot;
                s_arreq      <= 1'b1;
                s_ar_state   <= 1'b1;
            end
            else if (s_ar_busy && s_arack) begin
                s_arreq  <= 1'b0;
                s_ar_state <= 1'b0;
            end
        end
    end

    assign s_axil_arready = s_ar_idle;

    // M-side FSM
    reg m_ar_state;
    wire m_ar_idle = ~m_ar_state;
    wire m_ar_busy = m_ar_state;

    always @(posedge m_clk or posedge m_rst) begin
        if (m_rst) begin
            m_ar_state <= 1'b0;
            m_arack    <= 1'b0;
        end
        else begin
            if (m_ar_idle && m_arreq) begin
                m_ar_state <= 1'b1;
            end
            else if (m_ar_busy && m_axil_arready) begin
                m_ar_state <= 1'b0;
                m_arack    <= 1'b1;
            end
            else if (m_arack) begin
                m_arack <= 1'b0;
            end
        end
    end

    assign m_axil_araddr  = s_araddr_reg;
    assign m_axil_arprot  = s_arprot_reg;
    assign m_axil_arvalid = m_ar_busy;
    assign m_arack        = m_ar_state;

    // ========================================================================
    // Read Data Channel: M -> S
    // ========================================================================
    reg  [DATA_WIDTH-1:0] m_rdata_reg;
    reg  [1:0]            m_rresp_reg;
    reg                   m_rreq;
    wire                  s_rack;

    // Synchronizer for request
    reg [2:0] rreq_sync;
    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst)
