            m_rdata_reg <= {DATA_WIDTH{1'b0}};
            m_rresp_reg <= 2'b00;
            m_rreq      <= 1'b0;
        end
        else begin
            if (m_r_idle && m_axil_rvalid) begin
                m_rdata_reg <= m_axil_rdata;
                m_rresp_reg <= m_axil_rresp;
                m_rreq      <= 1'b1;
                m_r_state   <= 1'b1;
            end
            else if (m_r_busy && m_rack) begin
